let launchPackage = (packagePath, launchArguments) => {
    logger.debug('launchPackage')

    // Launch Application
    logger.info('Launching Application', appRootPath.path)

    const child = childProcess.spawn(packagePath, launchArguments, {
        cwd: appRootPath.path,
        detached: true,
        stdio: 'ignore'
    })

    // Fork
    child.unref()

    // Exit
    process.exit(0)
}
